import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        n = len(S)

        if n < 3:
            results.append("-1")
            continue

        max_prefix_len = 0
        for i in range(1, n):
            if S[:i] == S[n-i:]:
                max_prefix_len = i
            else:
                break

        if max_prefix_len >= n // 2 + 1:
            results.append("-1")
            continue

        min_suffix_start = n - max_prefix_len

        if min_suffix_start > max_prefix_len:
            gap_len = min_suffix_start - max_prefix_len - 1
            if gap_len > 0:
                results.append(str(gap_len))
            else:
                results.append("-1")
        else:
            results.append("-1")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
